import java.util.*;
import java.math.*;

public class Main {
    static final long INF = 1234567890L;
    static final int thousand = 47;
    static final double close_enough = 1e-8;
    static final int pattern = 9;
    static final double pi_value = 3.14159265358979323846;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        long mod = sc.nextLong();

        long[] factorial = new long[N + 1];
        long[] inv_factorial = new long[N + 1];

        factorial[0] = 1;
        inv_factorial[0] = 1;

        for (int i = 1; i <= N; i++) {
            factorial[i] = (factorial[i - 1] * i) % mod;
            inv_factorial[i] = (inv_factorial[i - 1] * power(i, mod - 2, mod)) % mod;
        }

        long[] count = new long[M + 1];
        long[] sum = new long[M + 1];

        Arrays.fill(count, 0);
        Arrays.fill(sum, 0);
        count[0] = 1;

        for (int m = 1; m <= M; m++) {
            for (int k = 0; k < m; k++) {
                long left_count = (count[k] * inv_factorial[k]) % mod;
                long right_count = (count[m - 1 - k] * inv_factorial[m - 1 - k]) % mod;
                long left_sum = (sum[k] * inv_factorial[k]) % mod;
                long right_sum = (sum[m - 1 - k] * inv_factorial[m - 1 - k]) % mod;

                count[m] = (count[m] + left_count * right_count % mod * (m + 1)) % mod;

                long term1 = (left_sum * right_sum) % mod;
                long term2 = (left_count * right_sum) % mod;
                long term3 = (left_sum * right_count) % mod;
                long sum_increment = (term1 + term2 + term3) % mod;
                sum_increment = (sum_increment * (m + 1)) % mod;

                long k_term = (long)k * (k + 1) + (long)(m - k) * (m - k - 1);
                k_term = k_term / 2;

                long sum_term = (left_count * right_count) % mod * (k_term % mod) % mod;

                sum[m] = (sum[m] + sum_increment + sum_term) % mod;
            }
            count[m] = (count[m] * factorial[m - 1]) % mod;
            sum[m] = (sum[m] * factorial[m - 1]) % mod;
        }

        long[][] count_ans = new long[N + 1][M + 1];
        long[][] sum_ans = new long[N + 1][M + 1];

        for (int i = 0; i <= N; i++) {
            Arrays.fill(count_ans[i], 0);
            Arrays.fill(sum_ans[i], 0);
        }

        count_ans[0][0] = 1;

        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= Math.min(i, M); j++) {
                count_ans[i][j] = count_ans[i - 1][j];
                sum_ans[i][j] = sum_ans[i - 1][j];

                if (j == i) {
                    count_ans[i][j] = (count_ans[i][j] + count[i] * inv_factorial[i]) % mod;
                    sum_ans[i][j] = (sum_ans[i][j] + sum[i] * inv_factorial[i]) % mod;
                }

                for (int k = 1; k <= Math.min(j, i - 1); k++) {
                    long c = (count[k] * inv_factorial[k]) % mod;
                    long s = (sum[k] * inv_factorial[k]) % mod;

                    long tempCount = (count_ans[i - 1 - k][j - k] * c) % mod;
                    count_ans[i][j] = (count_ans[i][j] + tempCount) % mod;

                    long tempSum = (sum_ans[i - 1 - k][j - k] * c + count_ans[i - 1 - k][j - k] * s) % mod;
                    sum_ans[i][j] = (sum_ans[i][j] + tempSum) % mod;
                }
            }
        }

        long answer = (sum_ans[N][M] * factorial[M]) % mod;
        System.out.println(answer);
        sc.close();
    }

    static long power(long base, long exp, long mod) {
        long result = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % mod;
            }
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    }
}
